package dev.skycraft.world;

import net.fabricmc.fabric.api.event.lifecycle.v1.ServerChunkEvents;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.block.Blocks;

/** Remove only tracked, deterministic stone/ore generated by the old excavator. */
public final class LegacyTerrainRepair {
 private record Pending(net.minecraft.server.level.ServerLevel level,net.minecraft.world.level.chunk.LevelChunk chunk) {}
 private static final java.util.concurrent.ConcurrentLinkedQueue<Pending> pending=new java.util.concurrent.ConcurrentLinkedQueue<>();
 private LegacyTerrainRepair() {}
 public static void register() {
  ServerChunkEvents.CHUNK_LOAD.register((level,chunk,newlyGenerated)->{
   if(!SkyDig.column(chunk).sections().isEmpty()) pending.add(new Pending(level,chunk));
  });
  // CHUNK_LOAD fires while the full-chunk future is still completing. Mutating
  // through Level there recursively waits for that same future. Defer until
  // the server finishes its tick, with a bounded number of chunks per tick.
  ServerTickEvents.END_SERVER_TICK.register(server->{
   for(int limit=0;limit<4;limit++) {
    var job=pending.poll(); if(job==null) break;
    repair(job.level(),job.chunk());
   }
  });
 }
 private static void repair(net.minecraft.server.level.ServerLevel level,net.minecraft.world.level.chunk.LevelChunk chunk) {
   var column=SkyDig.column(chunk); if(column.sections().isEmpty()) return;
   int removed=0;
   for(var section:column.sections()) {
    long[] bits=section.bits(); if(bits.length!=64) continue;
    for(int word=0;word<bits.length;word++) {
     long mask=bits[word];
     while(mask!=0) {
      int bit=word*64+Long.numberOfTrailingZeros(mask); mask&=mask-1;
      var pos=new BlockPos(chunk.getPos().getMinBlockX()+(bit&15),section.sectionY()*16+(bit>>8),chunk.getPos().getMinBlockZ()+((bit>>4)&15));
      var state=chunk.getBlockState(pos);
      if(state.equals(SkyDig.blockFor(level,pos,dev.skycraft.link.Proto.DIG_STONE))) {
       level.setBlock(pos,Blocks.AIR.defaultBlockState(),2|16); removed++;
      }
     }
    }
   }
   chunk.setAttached(SkyDig.DUG,SkyDig.DugColumn.EMPTY);
   dev.skycraft.SkyCraft.LOG.info("SLcraft terrain repair: removed {} tracked generated stone/ore blocks in chunk {}",removed,chunk.getPos());
 }
}
